    content: ".admin-main { padding-bottom: 80px; }\n.admin-topbar-label { justify-self: center; color: var(--muted); font-size: .72rem; font-weight: 760; letter-spacing: .08em; text-transform: uppercase; }\n.admin-heading { padding-top: 54px; }\n.admin-section { padding: 34px 0; border-top: 1px solid var(--line); }\n.admin-section h2 { margin: 4px 0 8px; font-family: var(--serif); font-size: 1.55rem; font-weight: 500; }\n.admin-copy, .admin-result { color: var(--muted); font-size: .78rem; }\n.admin-card-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }\n.admin-card { padding: 22px; border: 1px solid var(--line); border-radius: .45rem; background: rgba(255, 254, 249, .72); box-shadow: var(--shadow); }\n.admin-metric span { display: block; color: var(--muted); font-size: .68rem; font-weight: 760; letter-spacing: .05em; text-transform: uppercase; }\n.admin-metric strong { display: block; margin-top: 8px; font-family: var(--serif); font-size: 2.3rem; font-weight: 500; }\n.admin-metric small { color: var(--muted); font-size: .7rem; }\n.admin-two-column { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }\n.admin-form { display: grid; gap: 12px; margin-top: 20px; }\n.admin-form label:not(.admin-field) { display: flex; align-items: center; gap: 9px; font-size: .8rem; }\n.admin-form input[type=\"checkbox\"] { width: 17px; height: 17px; accent-color: var(--green); }\n.admin-field { display: grid; gap: 5px; color: var(--muted); font-size: .72rem; }\n.admin-field select, .diagnostic-form input { min-height: 40px; padding: .5rem .65rem; border: 1px solid var(--line); border-radius: .3rem; color: var(--ink); background: var(--white); }\n.admin-form button { justify-self: start; margin-top: 5px; }\n.admin-result { min-height: 1.4em; margin-bottom: 0; }\n.admin-section > .admin-card + .admin-card { margin-top: 14px; }\n.admin-table-wrap { overflow-x: auto; }\n.admin-table-wrap table { width: 100%; border-collapse: collapse; font-size: .74rem; }\n.admin-table-wrap th { color: var(--muted); font-size: .65rem; letter-spacing: .04em; text-align: left; text-transform: uppercase; }\n.admin-table-wrap th, .admin-table-wrap td { padding: 11px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }\n.admin-table-wrap td { white-space: nowrap; }\n.admin-table-wrap tr:last-child td { border-bottom: 0; }\n.admin-empty { color: var(--muted); font-size: .78rem; }\n.diagnostic-form { display: flex; gap: 8px; align-items: center; }\n.diagnostic-form input { width: min(290px, 38vw); }\n.diagnostic-lookup { margin-top: 18px; padding: 12px 14px; color: var(--blue); background: var(--blue-soft); border-radius: .3rem; font-size: .75rem; }\n@media (max-width: 800px) {\n  .admin-card-grid, .admin-two-column { grid-template-columns: 1fr 1fr; }\n  .admin-topbar-label { display: none; }\n}\n@media (max-width: 560px) {\n  .admin-card-grid, .admin-two-column { grid-template-columns: 1fr; }\n  .diagnostic-form { align-items: stretch; flex-direction: column; }\n  .diagnostic-form input { width: 100%; }\n}\n",
